/** This case's verdict judge reads real playthrough state — see buildRevealNarrative below for what's derived from it. */
export interface UntouchableContext {
  harmPatternConfirmed: boolean;
  timingTellConfirmed: boolean;
  institutionalComplicityConfirmed: boolean;
  samTrustCracked: boolean;
}

interface UntouchableStateSlice {
  witnessStages: Record<string, Record<string, number>>;
}

export function buildVerdictContext(state: UntouchableStateSlice): UntouchableContext {
  const reached = (witnessId: string, topicId: string, minStage = 0) =>
    (state.witnessStages[witnessId]?.[topicId] ?? -1) >= minStage;
  return {
    harmPatternConfirmed: reached("dana", "what_happened") || reached("theo", "the_pattern", 1),
    timingTellConfirmed: reached("sam", "what_he_overheard", 1),
    institutionalComplicityConfirmed: reached("theo", "the_old_file"),
    samTrustCracked: reached("sam", "what_he_overheard", 2),
  };
}

